    if round_num <= 3:
        return True

    # Count total cooperations so far
    coop_count = sum(1 for action in my_history if action)

    # If we have been very cooperative and recipient is highly reputable, cooperate
    if coop_count >= 7 and recipient_reputation > 0.8:
        return True

    # Determine threshold based on own cooperation experience
    if coop_count >= 3:
        threshold = -0.3   # more forgiving
    else:
        threshold = 0.1    # slightly cautious

    return recipient_reputation >= threshold

